& = & \left[ 1 + \alpha_m^{d_m} \beta_m^{k-d_m} \frac{\Pr(S_m = 1)}{\Pr(S_m = 0)} \right]^{-1} \nonumber \\

& = & \left( 1 + \alpha_m^{d_m} \beta_m^{k-d_m} \frac{\eta_m}{\zeta_m} \right)^{-1}_{,}
